exact_addition:
let selection_revision = env::var("KODA_IMPORT_SELECTION_REVISION")?.parse::<u64>()?;
let selected = android_tools::project_model::VariantId {
    module: env::var("KODA_IMPORT_SELECTED_MODULE")?,
    variant: env::var("KODA_IMPORT_SELECTED_VARIANT")?,
};
model.variant(&selected).context("actual native selected variant identity")?;
let binding = android_tools::import_facts::ImportFactsBinding {
    model_revision,
    selection_revision,
    selected_variants: vec![selected],
};
let import_facts = android_tools::import_facts::parse_import_facts(&output, &model, binding.clone())?;
import_facts.ensure_current(&model, &binding)?;
assert_eq!(import_facts.binding(), &binding);
let mut stale_model = binding.clone();
stale_model.model_revision = stale_model.model_revision.checked_add(1).context("revision overflow")?;
assert_eq!(import_facts.ensure_current(&model, &stale_model).err().context("stale model revision accepted")?.reason,
    android_tools::project_tree_facts::FactsUnavailableReason::Stale);
let mut stale_selection = binding.clone();
stale_selection.selection_revision = stale_selection.selection_revision.checked_add(1).context("revision overflow")?;
assert_eq!(import_facts.ensure_current(&model, &stale_selection).err().context("stale selection revision accepted")?.reason,
    android_tools::project_tree_facts::FactsUnavailableReason::Stale);
